cat > /tmp/check.sh <<'SH'
set -u
tr -d '\r' < /app/university_graph.ttl > /tmp/g.ttl
awk -v ref="2025-08-16" '
{
  if ($0 ~ /uni:isTaughtIn/) {
    course=$1; sub(/^uni:/,"",course);
    dept=$2; sub(/^uni:/,"",dept); sub(/[^A-Za-z0-9_].*/,"",dept);
    courseDept[course]=dept; next
  }
  if ($0 ~ /uni:isEnrolledIn/) {
    line=$0
    student=line; sub(/^uni:/,"",student); sub(/[ \t].*/,"",student)
    grad=""
    if (match(line, /uni:hasGraduationDate "[^"]+"/)) {
      g=substr(line, RSTART, RLENGTH); sub(/^.*"/,"",g); sub(/"$/,"",g); grad=g
    }
    cpart=line; sub(/^.*uni:isEnrolledIn/,"",cpart); sub(/;.*$/,"",cpart)
    n=split(cpart, cs, ",")
    for (i=1;i<=n;i++) {
      c=cs[i]; gsub(/[ \t]/,"",c); sub(/^uni:/,"",c); sub(/[^A-Za-z0-9_].*$/,"",c)
      if (c=="") continue
      if (c in courseDept) {
        d=courseDept[c]
        dstudents[d, student]=1
        if (grad=="" || grad > ref) dactive[d, student]=1
      } else {
        print "WARN: enrolled course with no department: " c " (student " student ")" > "/dev/stderr"
      }
    }
  }
}
END {
  for (k in dstudents) { split(k, a, SUBSEP); all[a[1]]++ }
  for (k in dactive)   { split(k, a, SUBSEP); act[a[1]]++ }
  print "department,totalEnrolled,currentlyEnrolled,passes_gt10"
  for (d in all) printf "%s,%d,%d,%s\n", d, all[d], act[d]+0, ((act[d]+0)>10 ? "YES":"no")
}
' /tmp/g.ttl | sort
echo "=== professors, roles, departments, dept universities/countries ==="
awk '
/^uni:[A-Za-z0-9_]+ a uni:Person/ { p=$1; sub(/^uni:/,"",p); role=""; deps=""; next }
/uni:role/ { role=$0; sub(/^.*uni:role "/,"",role); sub(/".*$/,"",role) }
/uni:worksIn/ { deps=$0; sub(/^.*uni:worksIn /,"",deps); sub(/ *\..*$/,"",deps); sub(/ *;.*$/,"",deps);
  print "PROF " p " | role=" role " | depts=" deps }
' /tmp/g.ttl
echo "=== department -> university -> country ==="
awk '
/uni:belongsTo/ { d=$1; sub(/^uni:/,"",d); u=$2; sub(/^uni:/,"",u); sub(/[^A-Za-z0-9_].*$/,"",u); deptUni[d]=u }
/uni:locatedInCountry/ { u=$1; sub(/^uni:/,"",u); c=$2; gsub(/[\";]/,"",c); uniCountry[u]=c }
END { for (d in deptUni) printf "%s -> %s (%s)\n", d, deptUni[d], uniCountry[deptUni[d]] }
' /tmp/g.ttl | sort
SH
bash /tmp/check.sh

