  sub(/^uni:/, "", sbj)
  pred = ""
  for (i = 2; i <= NF; i++) {
    t = $i
    term = ""
    if (t ~ /[.;,]$/) { term = substr(t, length(t)); t = substr(t, 1, length(t) - 1) }
    if (t == "") { if (term == ";" || term == ".") pred = ""; continue }
    if (pred == "") {
      if (t == "a") { pred = "a" } else if (t ~ /^uni:/) { pred = substr(t, 5) }
      if (term == ";" || term == ".") pred = ""
      continue
    }
    if (pred == "a") { if (term == ";" || term == ".") pred = ""; continue }
    v = t
    sub(/^uni:/, "", v)
    if (pred == "isTaughtIn") courseDept[sbj] = v
    else if (pred == "belongsTo") deptUni[sbj] = v
    else if (pred == "locatedInCountry") uniCountry[sbj] = v
    else if (pred == "worksIn") works[sbj] = works[sbj] " " v
    else if (pred == "role") role[sbj] = role[sbj] " " v
    else if (pred == "hasName") nm[sbj] = nm[sbj] " " v
    else if (pred == "isEnrolledIn") enr[sbj] = enr[sbj] " " v
    else if (pred == "hasEnrollmentDate") { g = v; gsub(/[^0-9-]/, "", g); ed[sbj] = g }
    else if (pred == "hasGraduationDate") { g = v; gsub(/[^0-9-]/, "", g); gd[sbj] = g }
    if (term == ";" || term == ".") pred = ""
  }
}
END {
  for (s in enr) {
    m = split(enr[s], cs, " ")
    for (i = 1; i <= m; i++) {
      c = cs[i]
      if (c == "") continue
      if (!(c in courseDept)) { print "WARN: no dept for course " c > "/dev/stderr"; continue }
      d = courseDept[c]
      ever[d, s] = 1
      if (ed[s] != "" && ed[s] <= REF && (gd[s] == "" || gd[s] > REF)) now[d, s] = 1
    }
  }
  for (k in ever) { split(k, a, SUBSEP); ec[a[1]]++ }
  for (k in now)  { split(k, a, SUBSEP); nc[a[1]]++ }
  print "== dept | ever | currently(REF=" REF ") | >10 =="
  for (d in ec) printf "%-30s %3d %3d %s\n", d, ec[d], nc[d] + 0, ((nc[d] + 0) > 10 ? "<== PASSES" : "")
  print ""
  print "== professors =="
  for (p in works) {
    full = (role[p] ~ /Professor/ && role[p] !~ /Assistant/ && role[p] !~ /Associate/) ? 1 : 0
    m = split(works[p], ds, " ")
    eu = 0; busy = 0; ctry = ""; bd = ""
    for (i = 1; i <= m; i++) {
      d = ds[i]; if (d == "") continue
      c = uniCountry[deptUni[d]]
      if (c in EU) eu = 1
      ctry = (ctry == "" ? c : ctry ", " c)
      if ((nc[d] + 0) > 10) { busy = 1; bd = bd " " d }
    }
    printf "%-24s full=%d eu=%d busy=%d ndeps=%d countries=[%s] busyDepts=[%s] SELECTED=%s\n", nm[p], full, eu, busy, m - 1, ctry, bd, ((full == 1 && eu == 1 && busy == 1) ? "YES" : "no")
  }
}
AWK
awk -v REF=2025-08-16 -f /tmp/an2.awk /tmp/clean.ttl
echo "=== predicates used by query vs present in graph ==="
for p in worksIn isTaughtIn belongsTo locatedInCountry hasName role isEnrolledIn hasEnrollmentDate hasGraduationDate; do
  q=$(grep -c "uni:$p" solution.sparql); g=$(grep -c "uni:$p" /tmp/clean.ttl)
  printf "%-22s inQuery=%s inGraph=%s %s\n" "$p" "$q" "$g" "$( [ "$g" -gt 0 ] && echo ok || echo MISSING )"
done"}

